def compute(vars):
    gross_profit_amount = vars["Gross Profit Amount"]
    sales_revenue = vars["Sales Revenue"]

    if gross_profit_amount is None or sales_revenue is None:
        cost_of_sales = None
    else:
        cost_of_sales = -gross_profit_amount + sales_revenue

    return {
        "value": cost_of_sales,
        "trace": {
            "parent_value": gross_profit_amount,
            "x0": sales_revenue,
            "Gross Profit Amount": gross_profit_amount,
            "Sales Revenue": sales_revenue,
            "Cost of Sales": cost_of_sales,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
